<?php
namespace App\Http\Controllers;
use App\Models\User;
use App\Services\ShopQueries;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\{Auth,DB,Hash,Storage};
use Illuminate\Support\Str;
use Illuminate\Validation\ValidationException;
class ShopController extends Controller {
 public function __construct(private ShopQueries $queries,private \App\Services\ShopNotifications $notifications){}
 private function fail(string $message):never {throw ValidationException::withMessages(['အချက်အလက်'=>$message]);}
 private function approved(Request $r):void {abort_unless($r->user()&&$r->user()->status==='approved',403,'ပိုင်ရှင်၏ အတည်ပြုချက်ကို စောင့်ဆိုင်းပေးပါ။');}
 private function owner(Request $r):void {$this->approved($r);abort_unless($r->user()->role==='owner',403,'လုပ်ငန်းပိုင်ရှင်သာ လုပ်ဆောင်နိုင်ပါသည်။');}
 public function register(Request $r){$v=$r->validate(['name'=>'required|string|max:100','phone'=>['required','regex:/^09[0-9]{7,11}$/','unique:users,phone'],'password'=>['required','string','min:8','max:128',new \App\Rules\SafePassword]]);return DB::transaction(function()use($v){$u=User::create($v);$this->notifications->owner('agent_registered','ကိုယ်စားလှယ်အသစ် စာရင်းသွင်းထားသည်','အတည်ပြုရန် စာရင်းတွင် ကြည့်ပါ။','agents',$u->id);return response()->json(['message'=>'စာရင်းသွင်းပြီးပါပြီ။ အတည်ပြုချက်ကို စောင့်ဆိုင်းပေးပါ။'],201);});}
 public function login(Request $r){$v=$r->validate(['phone'=>'required|string|max:20','password'=>'required|string|max:128','remember'=>'sometimes|boolean']);$credentials=['phone'=>$v['phone'],'password'=>$v['password']];Auth::guard('web')->setRememberDuration(60*24*30);if(!Auth::attempt($credentials,(bool)($v['remember']??false)))$this->fail('ဖုန်းနံပါတ် သို့မဟုတ် စကားဝှက် မမှန်ပါ။');if(Auth::user()->status!=='approved'){Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();abort(403,'ပိုင်ရှင်၏ အတည်ပြုချက် မရရှိသေးပါ။');}$r->session()->regenerate();return response()->json(Auth::user());}
 public function logout(Request $r){$v=$r->validate(['push_endpoint'=>'nullable|string|max:2048']);if(!empty($v['push_endpoint']))\App\Models\WebPushSubscription::where('user_id',$r->user()->id)->where('endpoint_hash',hash('sha256',$v['push_endpoint']))->delete();Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();return response()->json(['message'=>'အကောင့်ထွက်ပြီးပါပြီ။']);}
 public function password(Request $r){$this->approved($r);$v=$r->validate(['current_password'=>'required|string|max:128','password'=>['required','string','min:10','max:128','confirmed',new \App\Rules\SafePassword]]);if(!Hash::check($v['current_password'],$r->user()->password))$this->fail('လက်ရှိစကားဝှက် မမှန်ပါ။');$r->user()->password=$v['password'];$r->user()->save();Auth::logoutOtherDevices($v['password']);\App\Models\WebPushSubscription::where('user_id',$r->user()->id)->delete();$r->session()->regenerate();$r->session()->put('password_hash_web',Auth::user()->getAuthPassword());return response()->json(['message'=>'စကားဝှက် ပြောင်းပြီးပါပြီ။']);}
 public function state(Request $r){$this->approved($r);return response()->json($this->queries->state($r));}
 public function rankings(Request $r){$this->approved($r);return response()->json($this->queries->rankings($r));}
 public function options(Request $r,string $type){$this->approved($r);$this->queries->validate($r);if($type==='agents'){$this->owner($r);$q=DB::table('users')->where('role','agent')->where('status','approved')->select('id','name','phone','role','status');}else{abort_unless($type==='products',404);$q=$this->queries->productQuery(true)->where('stock','>',0);}
  if($search=trim($r->query('search',''))){$like='%'.str_replace(['!','%','_'],['!!','!%','!_'],$search).'%';$q->whereRaw("name LIKE ? ESCAPE '!'",[$like]);}
  $p=$this->queries->page($q->orderBy('id'),$r,$type==='agents'?'users':'products',10);if($type==='products')$p['rows']=array_map($this->queries->productRow(...),$p['rows']);return response()->json(['data'=>$p['rows'],'meta'=>$p['meta']]);
 }
 public function showOrder(Request $r,int $order){$this->approved($r);$o=$this->queries->orders($r,false)->where('orders.id',$order)->select('orders.*','users.name AS agent_name','products.name AS product_name')->first();abort_unless($o,404,'အော်ဒါကို မတွေ့ပါ။');return response()->json($this->queries->timestamp($o));}
 public function export(Request $r){$this->approved($r);$this->queries->validate($r);$query=$this->queries->orders($r)->select('orders.*','users.name AS agent_name','products.name AS product_name');return response()->streamDownload(function()use($query){$stream=fopen('php://output','w');fwrite($stream,"\xEF\xBB\xBF");fputcsv($stream,['အော်ဒါအမှတ်','ကိုယ်စားလှယ်','ဝယ်သူ','ဖုန်း','လိပ်စာ','ကုန်ပစ္စည်း','အရေအတွက်','စုစုပေါင်း','အခြေအနေ'],',','"','');$status=['pending'=>'မပို့ရသေး','sent'=>'ပို့ပြီး','cancelled'=>'ပယ်ဖျက်ပြီး'];foreach($query->lazyByIdDesc(500,'orders.id','id') as $o){$row=[$o->id,$o->agent_name,$o->customer,$o->phone,$o->address,$o->product_name,$o->quantity,$o->quantity*$o->unit_price,$status[$o->status]];$row=array_map(fn($v)=>preg_match('/^[\s\x00-\x1f]*[=+@-]/u',(string)$v)?"'".$v:$v,$row);fputcsv($stream,$row,',','"','');}fclose($stream);},'Ae Ae Business-အော်ဒါစာရင်း.csv',['Content-Type'=>'text/csv; charset=UTF-8']);}
 public function storeOrder(Request $r){$this->approved($r);$v=$r->validate(['request_key'=>'nullable|uuid','expected_price'=>'sometimes|integer|min:1|max:100000000','expected_commission'=>'sometimes|integer|min:0|max:100000000','product_id'=>'required|integer','agent_id'=>'sometimes|integer','customer'=>'required|string|max:100','phone'=>['required','regex:/^[0-9+\s\-]{7,20}$/'],'address'=>'required|string|max:1000','quantity'=>'required|integer|min:1|max:100000']);$agent=$r->user()->role==='owner'?($v['agent_id']??0):$r->user()->id;
  return DB::transaction(function()use($v,$agent){$u=User::where('id',$agent)->where('role','agent')->lockForUpdate()->first();if(!$u||$u->status!=='approved')$this->fail('အတည်ပြုပြီး ကိုယ်စားလှယ်ကို ရွေးချယ်ပါ။');if(!empty($v['request_key'])){$previous=DB::table('orders')->where('request_key',$v['request_key'])->first();if($previous){abort_unless($previous->agent_id===$agent&&$previous->product_id===(int)$v['product_id']&&$previous->quantity===(int)$v['quantity']&&$previous->customer===$v['customer']&&$previous->phone===$v['phone']&&$previous->address===$v['address'],409,'ထပ်မံတောင်းဆိုမှု၏ အချက်အလက် မကိုက်ညီပါ။');return response()->json(['id'=>$previous->id],200);}}
   $p=DB::table('products')->where('id',$v['product_id'])->lockForUpdate()->first();if(!$p||!$p->active)$this->fail('ဤကုန်ပစ္စည်းကို ရောင်းချခြင်း မရှိပါ။');if((isset($v['expected_price'])&&(int)$v['expected_price']!==$p->price)||(isset($v['expected_commission'])&&(int)$v['expected_commission']!==$p->commission))abort(409,'ကုန်ပစ္စည်းဈေး ပြောင်းလဲသွားပါပြီ။ ပစ္စည်းကို ပြန်ရွေးပါ။');if($p->stock<$v['quantity'])$this->fail('ကုန်ပစ္စည်း လက်ကျန် မလုံလောက်ပါ။');$id=DB::table('orders')->insertGetId(['request_key'=>$v['request_key']??null,'agent_id'=>$agent,'product_id'=>$p->id,'customer'=>$v['customer'],'phone'=>$v['phone'],'address'=>$v['address'],'quantity'=>$v['quantity'],'unit_price'=>$p->price,'unit_commission'=>$p->commission,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);DB::table('products')->where('id',$p->id)->update(['stock'=>$p->stock-$v['quantity'],'lock_version'=>$p->lock_version+1,'updated_at'=>now()]);$this->notifications->owner('order_created','အော်ဒါအသစ် ရရှိထားသည်','အော်ဒါစာရင်းတွင် ကြည့်ပါ။','orders',$id);return response()->json(['id'=>$id],201);
  },5);
 }
 public function status(Request $r,int $order){$this->owner($r);$v=$r->validate(['status'=>'required|in:sent,cancelled']);return DB::transaction(function()use($order,$v){$initial=DB::table('orders')->where('id',$order)->first();abort_unless($initial,404,'အော်ဒါကို မတွေ့ပါ။');User::where('id',$initial->agent_id)->lockForUpdate()->first();$o=DB::table('orders')->where('id',$order)->lockForUpdate()->first();if($o->status===$v['status'])return response()->json(['message'=>'မှတ်သားပြီး ဖြစ်ပါသည်။']);if($o->status!=='pending')$this->fail('ဤအော်ဒါကို ပြောင်းလဲ၍ မရတော့ပါ။');if($v['status']==='cancelled')DB::table('products')->where('id',$o->product_id)->update(['stock'=>DB::raw('stock + '.(int)$o->quantity),'lock_version'=>DB::raw('lock_version + 1'),'updated_at'=>now()]);DB::table('orders')->where('id',$order)->update(['status'=>$v['status'],'sent_at'=>$v['status']==='sent'?now():null,'updated_at'=>now()]);$this->notifications->record($o->agent_id,'order_'.$v['status'],$v['status']==='sent'?'အော်ဒါ ပို့ပြီးပါပြီ':'အော်ဒါ ပယ်ဖျက်ထားသည်','အော်ဒါအသေးစိတ်တွင် ကြည့်ပါ။','orders',$order);return response()->json(['message'=>'အခြေအနေ ပြောင်းလဲပြီးပါပြီ။']);},5);}
 public function productImage(Request $r,int $product){$this->approved($r);$p=DB::table('products')->where('id',$product)->when($r->user()->role!=='owner',fn($q)=>$q->where('active',true))->first(['image']);abort_unless($p,404);
  if(str_starts_with($p->image,'data:image/')){[$header,$base64]=explode(',',$p->image,2);return response(base64_decode($base64),200,['Content-Type'=>explode(';',substr($header,5))[0],'X-Content-Type-Options'=>'nosniff']);}
  abort_unless(str_starts_with($p->image,'shop-images/')&&Storage::disk('local')->exists($p->image),404);return response()->file(Storage::disk('local')->path($p->image));
 }
 public function product(Request $r,?int $product=null){$this->owner($r);$v=$r->validate(['name'=>'required|string|max:150','description'=>'required|string|max:2000','price'=>'required|integer|min:1|max:100000000','commission'=>'required|integer|min:0|lte:price','stock'=>'required|integer|min:0|max:1000000','image'=>'required|string|max:3000000','active'=>'required|boolean','lock_version'=>$product?'required|integer|min:0':'sometimes|integer|min:0']);$newFile=null;$oldFile=null;
  try{$result=DB::transaction(function()use($v,$product,&$newFile,&$oldFile){$current=$product?DB::table('products')->where('id',$product)->lockForUpdate()->first():null;if($product)abort_unless($current,404,'ကုန်ပစ္စည်း မတွေ့ပါ။');if($current)abort_unless((int)$v['lock_version']===$current->lock_version,409,'ပစ္စည်းစာရင်း ပြောင်းလဲသွားပါပြီ။ ပြန်ဖွင့်ပြီး ပြင်ဆင်ပါ။');$data=$v;
   $image=$v['image'];if($current&&$image==="/api/products/$product/image"){$data['image']=$current->image;}elseif(str_starts_with($image,'data:')){if(!preg_match('/^data:image\/(jpeg|png|webp);base64,([A-Za-z0-9+\/=]+)$/D',$image,$m))$this->fail('ဓာတ်ပုံအမျိုးအစား မမှန်ပါ။');$bytes=base64_decode($m[2],true);$info=$bytes!==false?@getimagesizefromstring($bytes):false;if(!$info||strlen($bytes)>2097152||$info[0]>6000||$info[1]>6000||!in_array($info['mime'],['image/jpeg','image/png','image/webp']))$this->fail('ဓာတ်ပုံသည် မှန်ကန်ပြီး ၂ မီဂါဘိုက်အောက် ရှိရပါမည်။');$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$info['mime']];$newFile='shop-images/'.Str::uuid().'.'.$ext;abort_unless(Storage::disk('local')->put($newFile,$bytes),500,'ဓာတ်ပုံ သိမ်းဆည်း၍ မရပါ။');$data['image']=$newFile;}elseif(!in_array($image,['/products/cream.jpg','/products/lipstick.jpg'])){$this->fail('ဓာတ်ပုံတစ်ပုံ ရွေးချယ်ပါ။');}
   $data['lock_version']=$current?$current->lock_version+1:0;$data['updated_at']=now();if($current){if($current->image!==$data['image']&&str_starts_with($current->image,'shop-images/'))$oldFile=$current->image;DB::table('products')->where('id',$product)->update($data);return ['id'=>$product];}return ['id'=>DB::table('products')->insertGetId([...$data,'created_at'=>now()])];});}catch(\Throwable $e){if($newFile)Storage::disk('local')->delete($newFile);throw $e;}if($oldFile)Storage::disk('local')->delete($oldFile);return response()->json($result);
 }
 public function agent(Request $r,int $agent){$this->owner($r);$v=$r->validate(['status'=>'required|in:approved,rejected']);return DB::transaction(function()use($agent,$v){$u=User::where('id',$agent)->where('role','agent')->lockForUpdate()->firstOrFail();$old=$u->status;$u->status=$v['status'];$u->save();if($old!==$u->status&&$u->status==='approved')$this->notifications->record($u->id,'agent_approved','အကောင့် အတည်ပြုပြီးပါပြီ','အကောင့်ဝင်ပြီး အော်ဒါတင်နိုင်ပါပြီ။','dashboard');if($u->status==='rejected')\App\Models\WebPushSubscription::where('user_id',$u->id)->delete();return response()->json(['message'=>'အတည်ပြုမှု ပြင်ဆင်ပြီးပါပြီ။']);},5);}
 public function payout(Request $r){$this->owner($r);$v=$r->validate(['request_key'=>'nullable|uuid','agent_id'=>'required|integer','amount'=>'required|integer|min:1|max:1000000000','reference'=>'required|string|max:250']);return DB::transaction(function()use($v){$u=User::where('id',$v['agent_id'])->where('role','agent')->lockForUpdate()->first();if(!$u)$this->fail('ကိုယ်စားလှယ် မတွေ့ပါ။');if(!empty($v['request_key'])){$previous=DB::table('payouts')->where('request_key',$v['request_key'])->first();if($previous){abort_unless($previous->agent_id===$u->id&&$previous->amount===(int)$v['amount']&&$previous->reference===$v['reference'],409,'ထပ်မံတောင်းဆိုမှု၏ အချက်အလက် မကိုက်ညီပါ။');return response()->json(['id'=>$previous->id]);}}
   $balance=$this->queries->agentBalances([$u->id])[$u->id]['balance'];if($v['amount']>$balance)$this->fail('ကျန်ရှိငွေထက် ပိုမိုငွေရှင်း၍ မရပါ။');$id=DB::table('payouts')->insertGetId([...$v,'created_at'=>now(),'updated_at'=>now()]);$this->notifications->record($u->id,'payout_recorded','ကော်မရှင် ငွေရှင်းပြီးပါပြီ','ငွေရှင်းမှတ်တမ်းတွင် ကြည့်ပါ။','earnings',$id);return response()->json(['id'=>$id],201);},5);}
}
